static struct ef4_tx_buffer * ef4_tx_map_chunk ( struct ef4_tx_queue * tx_queue , dma_addr_t dma_addr , size_t len ) { const struct ef4_nic_type * nic_type = tx_queue -> efx -> type ; struct ef4_tx_buffer * buffer ; unsigned int dma_len ; { buffer = ef4_tx_queue_get_insert_buffer ( tx_queue ) ; dma_len = nic_type -> tx_limit_len ( tx_queue , dma_addr , len ) ; buffer -> len = dma_len ; buffer -> dma_addr = dma_addr ; len -= dma_len ; dma_addr += dma_len ; ++ tx_queue -> insert_count ; } len ; return buffer ; } 